            "description": "Font file",
            "default": "gbenor.shx"
          },
          "big_font": {
            "type": "string",
            "description": "Big font for CJK characters (SHX fonts only; default gbcbig.shx)"
          },
          "width_factor": {
            "type": "number",
            "description": "Character width factor",
            "exclusiveMinimum": 0,
            "default": 1.0
          },
